SELECT 
FROM 
WHERE snapshottime BETWEEN #{startTime} AND #{endTime}
ORDER BY snapshottime DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM 
WHERE snapshottime BETWEEN #{startTime} AND #{endTime}

SELECT 
FROM 
WHERE 1=1

    AND platenumber LIKE CONCAT('%', #{platenumber}, '%')


    AND deviceid = #{deviceid}


    AND gantrycode = #{gantrycode}


    AND direction = #{direction}


    AND snapshottime >= #{snapshottime}

ORDER BY snapshottime DESC

