    AND platenumber LIKE CONCAT('%', #{record.platenumber}, '%')


    AND deviceid = #{record.deviceid}


    AND gantrycode = #{record.gantrycode}


    AND direction = #{record.direction}


    AND snapshottime >= #{record.snapshottime}

